package com.loopers.application.payment
import com.loopers.domain.payment.*;import com.loopers.support.error.*;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional
// Hides: one-dispatch fencing and UNKNOWN reconciliation sequencing.
@Component class PaymentFacade(private val repo:PaymentIntentRepository,private val gateway:PaymentGateway){@Transactional fun dispatch(orderId:Long,attempt:String,amount:Long):PaymentIntent{repo.findByAttempt(orderId,attempt)?.let{return it};val p=repo.save(PaymentIntent(orderId,attempt,amount));p.requested();try{val r=gateway.create(USER,PaymentGateway.Request(p.providerOrderId,"SAMSUNG","1234-1234-1234-1234",amount,"http://localhost:8080/api/v1/payments/callback"));p.settle(r.transactionKey,PaymentIntent.Status.valueOf(r.status))}catch(_:RuntimeException){p.unknown()};return repo.save(p)};@Transactional fun reconcile(id:Long):PaymentIntent{val p=repo.find(id)?:throw CoreException(ErrorType.NOT_FOUND);if(p.status!=PaymentIntent.Status.UNKNOWN)return p;val found=gateway.findByOrderId(USER,p.providerOrderId);if(found.size==1)p.settle(found.first().transactionKey,PaymentIntent.Status.valueOf(found.first().status))else if(found.size>1)throw CoreException(ErrorType.CONFLICT,"multiple provider effects");return repo.save(p)};@Transactional fun callback(orderId:String,transactionKey:String,status:String):PaymentIntent{val p=repo.findByProviderOrderId(orderId)?:throw CoreException(ErrorType.NOT_FOUND);p.settle(transactionKey,PaymentIntent.Status.valueOf(status));return repo.save(p)};companion object{const val USER="135135"}}
